const conn = $('getConnections').item.json;
const rules = $('getRules').item.json;
const ctx = $('getUserContext').item.json;
const userRes = $('userByPhone').item.json;
const body = $('Webhook Chatwoot').item.json.body;
const NL = String.fromCharCode(10);
const docText = (function(){ try { return $('Le anexo').item.json.text || ''; } catch(e){ return ''; } })();
const rawMsg = body.content || '';
let userMsg = rawMsg;
if (docText) { userMsg = (rawMsg ? rawMsg + NL + NL : '') + '[DOCUMENTO/IMAGEM ENVIADO PELO CLIENTE - conteudo extraido]:' + NL + docText; }
if (!userMsg) { userMsg = '(o cliente enviou algo sem texto legivel)'; }
const u = userRes.user || null;
const userName = (u && u.name) || (body.sender && body.sender.name) || 'cliente';
const rulesText = rules.rules || '';
const docs = (rules.docs || []).map(d => '# ' + d.title + NL + (d.content || '')).join(NL + NL);
const pending = (ctx.pending_bills || []).map(b => '- id:' + b.id + ' ' + b.name + ' R$' + b.amount + ' venc ' + b.due_date).join(NL);
const cats = (ctx.categories || []).map(c => c.name + '(' + c.type + ')').join(', ');
const accts = (ctx.accounts || []).map(a => a.name).join(', ');
const mt = ctx.month_totals || {};
const now = new Date();
const hoje = now.toISOString().slice(0,10);
const lines = [];
lines.push('Voce e o assistente financeiro da Lumers (a marca chama-se *Lumers Flow*). Seja caloroso, humano e objetivo. Responda em pt-BR e entenda a intencao do usuario.');
lines.push('DATA DE HOJE: ' + hoje + '. Mes atual: ' + (now.getMonth()+1) + ', ano: ' + now.getFullYear() + '.');
lines.push('FORMATACAO DA RESPOSTA (campo reply) - obrigatorio:');
lines.push('- Escreva o nome da marca SEMPRE como *Lumers Flow* em negrito (asteriscos do WhatsApp).');
lines.push('- Nunca responda em um paragrafo unico: quebre a mensagem em varias linhas curtas.');
lines.push('- Ao apresentar opcoes, coloque UMA opcao por linha no formato: *1* - Texto da opcao.');
lines.push('- Deixe uma linha em branco antes da lista de opcoes e destaque valores e nomes em *negrito*.');
lines.push('- Use no maximo 1 emoji por mensagem e mantenha o tom caloroso, humano e objetivo.');
lines.push('SEJA PROATIVO E CONDUZA ATE A ACAO - regra central:');
lines.push('- NUNCA apenas descreva/confirme e pare. TODA resposta deve terminar com uma PERGUNTA clara ou um proximo passo, ate concluir um registro.');
lines.push('- Se nao entendeu a intencao do cliente, faca perguntas para esclarecer ate saber o que fazer. Nunca finalize sem proximo passo.');
lines.push('- Faca UMA pergunta objetiva por vez (nao despeje todas juntas). Use o contexto para nao perguntar o obvio.');
lines.push('DOCUMENTO/IMAGEM: quando a mensagem do usuario contiver [DOCUMENTO/IMAGEM ENVIADO PELO CLIENTE]:');
lines.push('- Confirme em 1 linha o que entendeu (valor, descricao, data).');
lines.push('- Em seguida PERGUNTE o que ele quer fazer, oferecendo opcoes numeradas, por exemplo:');
lines.push('  *1* - Registrar como *despesa*');
lines.push('  *2* - Registrar como *receita*');
lines.push('  *3* - Nao registrar agora');
lines.push('- Depois pergunte os dados que faltam UM DE CADA VEZ (data/periodo, categoria, conta) ate ter o suficiente para emitir a action addTransaction.');
if (rulesText) lines.push('REGRAS DO ADMIN:' + NL + rulesText);
if (docs) lines.push('BASE DE CONHECIMENTO:' + NL + docs);
lines.push('CLIENTE: ' + userName + ' (userId: ' + (u ? u.id : 'desconhecido') + ')');
lines.push('CONTAS: ' + (accts || 'nenhuma'));
lines.push('CATEGORIAS: ' + (cats || 'nenhuma'));
lines.push('CONTAS A PAGAR PENDENTES:' + NL + (pending || 'nenhuma'));
lines.push('TOTAIS DO MES: receita R$' + (mt.income || 0) + ', despesa R$' + (mt.expense || 0));
lines.push('');
lines.push('Responda SEMPRE em JSON valido: {"reply":"texto ao cliente","action":null}');
lines.push('Quando ja tiver dados suficientes, troque action por um objeto pronto para POST na ponte:');
lines.push('addTransaction -> {"op":"addTransaction","userId":"<id>","record":{"name":"...","amount":0,"transaction_type":"expense","status":"pending","due_date":"YYYY-MM-DD","month":0,"year":0,"category_id":""}}');
lines.push('markBillPaid -> {"op":"markBillPaid","txId":"<id da conta pendente>","paidDate":"YYYY-MM-DD"}');
lines.push('createCategory -> {"op":"createCategory","userId":"<id>","record":{"name":"...","type":"expense","icon":"pacote"}}');
lines.push('createAccount -> {"op":"createAccount","userId":"<id>","record":{"name":"...","bank_name":"","type":"checking","initial_balance":0}}');
lines.push('Nunca invente ids; use os ids do contexto. Enquanto faltar dado para agir, mantenha action=null E faca a proxima pergunta.');
const system = lines.join(NL);
const hist = (function(){ try { return $('Historico').item.json.history || []; } catch(e){ return []; } })();
const curId = body.id;
const messages = [{ role: 'system', content: system }];
for (const h of hist) { if (h && h.content && h.id !== curId) messages.push({ role: h.role, content: h.content }); }
messages.push({ role: 'user', content: userMsg });
return [{ json: { messages: messages, userMsg: userMsg, system: system } }];

let content = '';
try { content = $json.choices[0].message.content; } catch (e) { content = ''; }
let parsed;
try { parsed = JSON.parse(content); } catch (e) { parsed = { reply: content || 'Desculpe, nao consegui entender. Pode repetir?', action: null }; }
let action = parsed.action || null;
if (action && (action.op === 'addTransaction' || action.op === 'createCategory' || action.op === 'createAccount') && !action.userId) {
  const u = ($('userByPhone').item.json.user) || null;
  if (u) action.userId = u.id;
}
return [{ json: { reply: parsed.reply || 'Ok!', action: action, hasAction: !!action } }];
